<span class="line"><span style="color:#ABB2BF;">    losses </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [e[</span><span style="color:#98C379;">&quot;loss&quot;</span><span style="color:#ABB2BF;">] </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> e </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> entries </span><span style="color:#C678DD;">if</span><span style="color:#98C379;"> &quot;loss&quot;</span><span style="color:#C678DD;"> in</span><span style="color:#ABB2BF;"> e]</span></span>
