<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> rewards </span><span style="color:#C678DD;">and</span><span style="color:#ABB2BF;"> rewards[</span><span style="color:#56B6C2;">-</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;"> rewards[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">]:</span></span>
